  "lines": ["한 여인은 이 아들이 내 아들이라 하고 다른 여인은 아니라 하는구나. 칼을 가져와 아이를 나누어라.", "아이를 죽이지 말고 저 여인에게 주어라. 그 여인이 참 어머니임을 알겠다."],
